import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int count = 0;

        private int readByte() {
            if (ptr >= count) {
                try {
                    count = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (count <= 0) return -1;
                ptr = 0;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -res : res;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        if (n <= 0) return;

        int[] head = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            head[i] = -1;
        }

        int m = (n - 1) * 2;
        int[] to = new int[m];
        int[] next = new int[m];
        int edgeCount = 0;

        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();

            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        int[] order = new int[n];
        int[] parent = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        int headQueue = 0;
        int tailQueue = 0;

        order[tailQueue++] = 1;
        visited[1] = true;

        while (headQueue < tailQueue) {
            int u = order[headQueue++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    order[tailQueue++] = v;
                }
            }
        }

        int[] sz = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            sz[i] = 1;
        }

        int minDiff = n;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int p = parent[u];
            if (p != 0) {
                sz[p] += sz[u];
                int diff = Math.abs(n - 2 * sz[u]);
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        System.out.println(minDiff);
    }
}
